import 'package:audioplayers/audioplayers.dart';

import 'app_state.dart';

/// Plays the original FOUR / SIX / WICKET sounds (generated by scripts/generate_sounds.py).
class SoundPlayer {
  SoundPlayer(this.state);
  final AppState state;
  final AudioPlayer _player = AudioPlayer();

  Future<void> play(String highlight) async {
    if (!state.sound || state.volume <= 0) return;
    if (!const ['four', 'six', 'wicket'].contains(highlight)) return;
    try {
      await _player.stop();
      await _player.setVolume(state.volume);
      await _player.play(AssetSource('sounds/$highlight.wav'));
    } catch (_) {
      // Sound is optional; never break the live view because audio failed.
    }
  }

  void dispose() => _player.dispose();
}
